bicepWiring.envVarsInjection:
env: [
  { name: 'AZURE_CLIENT_ID', value: managedIdentity.properties.clientId }
  { name: 'AZURE_COSMOS_ENDPOINT', value: cosmosDb.outputs.cosmosEndpoint }
  { name: 'AZURE_OPENAI_ENDPOINT', value: openai.outputs.openAiEndpoint }
  // ... inject ALL downstream service endpoints here
]

bicepWiring.scaleRule:
scale: {
  minReplicas: 0
  maxReplicas: 10
  rules: [{
    name: 'http-scaling'
    http: { metadata: { concurrentRequests: '50' } }
  }]
}

sdkInitPattern.typescript:
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential({
  managedIdentityClientId: process.env.AZURE_CLIENT_ID
});
